const products=[
{id:'boj',brand:'BEAUTY OF JOSEON',name:'Relief Sun',formula:'Rice + Niacinamide · SPF 50+ PA++++',yes:28,no:5},
{id:'eltamd',brand:'ELTAMD',name:'UV Clear',formula:'Untinted · Broad-Spectrum SPF 46',yes:32,no:5},
{id:'skin1004',brand:'SKIN1004',name:'Hyalu-Cica Water-Fit Sun Serum UV',formula:'SPF 50 · US formula',yes:25,no:6},
{id:'supergoop',brand:'SUPERGOOP!',name:'Unseen Sunscreen',formula:'SPF 50',yes:26,no:8},
{id:'roundlab',brand:'ROUND LAB',name:'Birch Moisturizing Sunscreen UVLock',formula:'Broad Spectrum SPF 50 · US formula',yes:22,no:5},
{id:'medicube',brand:'MEDICUBE',name:'No Cast Just Glow Collagen Sunscreen',formula:'SPF 50',yes:20,no:7},
{id:'mixsoon',brand:'MIXSOON',name:'Bean Sunscreen',formula:'SPF 50',yes:18,no:6},
{id:'innisfree',brand:'INNISFREE',name:'Daily UV Defense Sunscreen',formula:'Broad Spectrum SPF 50+',yes:24,no:8}];
const KEY='vouch-sunscreen-v1';
const initial=()=>({votes:{},nomination:null,round:1});
let state;try{state=JSON.parse(localStorage.getItem(KEY))||initial()}catch{state=initial()}
let screen='home',index=0;const app=document.getElementById('app');
function save(){try{localStorage.setItem(KEY,JSON.stringify(state))}catch{}}
function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function score(p){return (10*(p.yes+(state.votes[p.id]==='yes'?1:0))/(p.yes+p.no+(['yes','no'].includes(state.votes[p.id])?1:0))).toFixed(1)}
function go(s){screen=s;render();window.scrollTo({top:0,behavior:'instant'})}
function render(){if(screen==='home')home();else if(screen==='game')game();else board()}
function home(){app.innerHTML=`<section class="hero"><div><span class="tag"><i class="dot"></i> SKINCARE / SUNSCREEN / ROUND 01</span><h1>Big SPF.<br><em>Bigger opinions.</em></h1><p class="intro">The viral ones. The holy grails. The “never again”s. Tell us which sunscreens you vouch for, then see the Wharton edit.</p><button class="primary" data-action="start">Vouch or pass <span>↗</span></button><p class="caption">8 sunscreens. Your honest take. About a minute.<br>Only vote on ones you’ve tried.</p></div><div class="hero-art" aria-label="Sunscreens from the edit"><span class="art-label">The sunscreen edit.</span><img src="assets/boj.png" alt="Beauty of Joseon Relief Sun"><img class="second" src="assets/supergoop.png" alt="Supergoop Unseen Sunscreen"><div class="sticker">Worth the<br>hype?<br>↗</div></div></section><div class="steps"><div>01 <span>Drop your verdicts</span></div><div>02 <span>Reveal the edit</span></div><div>03 <span>Add your holy grail</span></div></div>`}
function game(){const p=products[index];app.innerHTML=`<section class="game"><div class="game-top"><span>THE SUNSCREEN EDIT</span><span>${index+1} of ${products.length}</span></div><div class="progress" aria-label="Product ${index+1} of ${products.length}">${products.map((_,i)=>`<i class="${i<=index?'done':''}"></i>`).join('')}</div><article class="product-card"><div class="product-photo"><span class="category">SPF, PLEASE.</span><img src="assets/${p.id}.png" alt="${p.brand} ${p.name}"></div><div class="product-content"><p class="brand">${p.brand}</p><h2>${p.name}</h2><p class="formula">${p.formula}</p></div></article><p class="vote-hint">Tried it? Would you recommend it?</p><div class="vote-actions"><button class="vouch" data-vote="yes">Vouch 👍</button><button class="pass" data-vote="no">Pass 👎</button></div><button class="skip" data-vote="skip">Haven’t tried →</button>${index>0?'<button class="undo" data-action="back">← Previous sunscreen</button>':''}${index>=5?'<button class="skip" data-action="board">Reveal the edit ↗</button>':''}</section>`}
function board(){const sorted=[...products].sort((a,b)=>Number(score(b))-Number(score(a)));const n=state.nomination;app.innerHTML=`<section class="board"><div class="board-head"><p class="eyebrow">VOUCH / THE WHARTON EDIT</p><h1>The SPF standings.</h1><p>Some live up to the hype. You help decide.</p><span class="sample-label">Prototype · sample rankings + your takes</span></div><div class="board-topline"><span>ROUND 01 / SUNSCREEN</span><span>VOUCH SCORE</span></div>${sorted.map((p,i)=>`<div class="rank-row"><span class="rank">${String(i+1).padStart(2,'0')}</span><img src="assets/${p.id}.png" alt="${p.name}"><div class="rank-info"><p class="brand">${p.brand}</p><h3>${p.name}</h3>${state.votes[p.id]&&state.votes[p.id]!=='skip'?`<span class="your-vote">You ${state.votes[p.id]==='yes'?'vouched 👍':'passed 👎'}</span>`:''}</div><span class="score">${score(p)}</span></div>`).join('')}<section class="nominate" id="nominate"><p class="eyebrow">MAKE ROOM FOR YOUR FAVORITE</p><h2>Your holy grail missing?</h2><p>Nominate a sunscreen. If four people nominate it, it joins the next round.</p>${n?`<div class="confirmation" role="status"><strong>${n.qualified?'It’s in for the next round. ✳':'You put it on our radar. ✳'}</strong><br>${esc(n.name)}${n.qualified?'<br>Your nomination made it four. Added to the next-round lineup.':'<br>We’ll look it up and match it with other nominations.'}</div>`:`<form id="nomination-form"><label for="nomination-name">Which sunscreen is missing?</label><div class="input-row"><input id="nomination-name" name="name" placeholder="e.g., Beauty of Joseon Relief Sun" autocomplete="off" maxlength="120" required><button class="primary" type="submit">Nominate ↗</button></div><p id="nomination-error" role="alert"></p></form>`}${n?.qualified?`<div class="queue"><p class="eyebrow">NEXT ROUND</p><strong>${esc(n.name)}</strong> <span>· Unrated</span></div>`:''}</section><div class="board-bottom"><button class="text-button" data-action="start">${Object.keys(state.votes).length?'Revisit your takes':'Play Vouch or Pass'} ↗</button></div></section>`;document.getElementById('nomination-form')?.addEventListener('submit',e=>{e.preventDefault();const name=new FormData(e.target).get('name').trim().replace(/\s+/g,' ');const error=document.getElementById('nomination-error');if(name.length<2){error.textContent='Add a sunscreen name first.';return}const normalized=name.toLowerCase().replace(/[^a-z0-9]/g,'');const existing=products.find(p=>normalized===p.id||normalized===(p.brand+' '+p.name).toLowerCase().replace(/[^a-z0-9]/g,'')||normalized===p.name.toLowerCase().replace(/[^a-z0-9]/g,''));if(existing){error.textContent='That sunscreen is already on the board. Your verdict is welcome above!';return}const qualified=/isntree/.test(normalized)&&/waterysungel/.test(normalized);state.nomination={name,qualified,status:qualified?'next-round':'pending-lookup'};save();board();document.getElementById('nominate').scrollIntoView({behavior:'smooth',block:'center'})})}
document.addEventListener('click',e=>{const vote=e.target.closest('[data-vote]');if(vote){state.votes[products[index].id]=vote.dataset.vote;save();if(index===products.length-1)go('board');else{index++;render()}return}const action=e.target.closest('[data-action]')?.dataset.action;if(action==='home')go('home');if(action==='board')go('board');if(action==='start'){index=0;go('game')}if(action==='back'){index=Math.max(0,index-1);render()}});
document.getElementById('prototype').onclick=()=>document.getElementById('info').showModal();document.getElementById('reset').onclick=()=>{state=initial();save();document.getElementById('info').close();go('home')};render();
